/* Welford's online update keeps variance stable for large baselines. */
void update_stats(double value, int count, double *mean, double *m2) {
    double delta = value - *mean;
    *mean += delta / count;
    double delta2 = value - *mean;
    *m2 += delta * delta2;
}
